  natt1 = 25
  nexc1 = 15
  nexc2 = 14
  nexc3 = 15
  ev[1] = 0.0
  ev[2] = 2.0 * cnsts.emass / (47.998199462890625 * cnsts.amu)
  ev[3] = 12.75
  ev[4] = 0.0
  ev[5] = 0.0
