        fdo j, 2, ndata:
          if en <= xen[j]: break L20
        j = ndata
      # USE LOG INTERPOLATION
      y1 = ln(yxsec[j - 1])
      y2 = ln(yxsec[j])
      x1 = ln(xen[j - 1])
      x2 = ln(xen[j])
      a = (y2 - y1) / (x2 - x1)
