      qin[4, i] = 0.013299999758601189 * ln((1.0 + efac) / (1.0 - efac)) / en
      qin[4, i] = a * en + b + qin[4, i]
      qin[4, i] = qin[4, i] * 1.0 / (1.0 + apopv) * 1e-16
    # V1 + V3   ( STRETCH MODES )
    qin[5, i] = 0.0
    if not (en <= ein[5]):
      block L420:
        fdo j, 2, nvib2:
          if en <= xvib2[j]: break L420
        j = nvib2
      a = (yvib2[j] - yvib2[j - 1]) / (xvib2[j] - xvib2[j - 1])
      b = (xvib2[j - 1] * yvib2[j] - xvib2[j] * yvib2[j - 1]) / (xvib2[j - 1] - xvib2[j])
      efac = sqrt(1.0 - ein[5] / en)
      qin[5, i] = 0.09000000357627869 * ln((1.0 + efac) / (1.0 - efac)) / en
      qin[5, i] = (a * en + b + qin[5, i]) * 1e-16
    # V12 +V23
    qin[6, i] = 0.0
    if not (en <= ein[6]):
      block L520:
        fdo j, 2, nvib3:
          if en <= xvib3[j]: break L520
        j = nvib3
      a = (yvib3[j] - yvib3[j - 1]) / (xvib3[j] - xvib3[j - 1])
      b = (xvib3[j - 1] * yvib3[j] - xvib3[j] * yvib3[j - 1]) / (xvib3[j - 1] - xvib3[j])
      qin[6, i] = (a * en + b) * 1e-16
    # V13+2V1+2V3
    qin[7, i] = 0.0
    if not (en <= ein[7]):
      block L620:
        fdo j, 2, nvib4:
          if en <= xvib4[j]: break L620
        j = nvib4
      a = (yvib4[j] - yvib4[j - 1]) / (xvib4[j] - xvib4[j - 1])
      b = (xvib4[j - 1] * yvib4[j] - xvib4[j] * yvib4[j - 1]) / (xvib4[j - 1] - xvib4[j])
      qin[7, i] = (a * en + b) * 1e-16
    # HIGHER HARMONICS
    qin[8, i] = 0.0
    if not (en <= ein[8]):
      block L720:
        fdo j, 2, nvib5:
          if en <= xvib5[j]: break L720
        j = nvib5
      a = (yvib5[j] - yvib5[j - 1]) / (xvib5[j] - xvib5[j - 1])
      b = (xvib5[j - 1] * yvib5[j] - xvib5[j] * yvib5[j - 1]) / (xvib5[j - 1] - xvib5[j])
      qin[8, i] = (a * en + b) * 1e-16
    # EXCITATION  CHAPPUIS BAND
    qin[9, i] = 0.0
    if not (en <= ein[9]):
      block L820:
        fdo j, 2, nexc1:
          if en <= xexc1[j]: break L820
        j = nexc1
      a = (yexc1[j] - yexc1[j - 1]) / (xexc1[j] - xexc1[j - 1])
      b = (xexc1[j - 1] * yexc1[j] - xexc1[j] * yexc1[j - 1]) / (xexc1[j - 1] - xexc1[j])
      qin[9, i] = (a * en + b) * 1e-16
    # EXCITATION  HARTLEY BAND
    qin[10, i] = 0.0
    if not (en <= ein[10]):
      block L920:
        fdo j, 2, nexc2:
          if en <= xexc2[j]: break L920
        j = nexc2
      a = (yexc2[j] - yexc2[j - 1]) / (xexc2[j] - xexc2[j - 1])
      b = (xexc2[j - 1] * yexc2[j] - xexc2[j] * yexc2[j - 1]) / (xexc2[j - 1] - xexc2[j])
      qin[10, i] = (a * en + b) * 1e-16
    # EXCITATION
    qin[11, i] = 0.0
    if not (en <= ein[11]):
      block L1020:
        fdo j, 2, nexc3:
          if en <= xexc3[j]: break L1020
        j = nexc3
      a = (yexc3[j] - yexc3[j - 1]) / (xexc3[j] - xexc3[j - 1])
      b = (xexc3[j - 1] * yexc3[j] - xexc3[j] * yexc3[j - 1]) / (xexc3[j - 1] - xexc3[j])
      qin[11, i] = (a * en + b) * 1e-16
    q[1, i] = q[2, i] + q[3, i] + q[4, i] + qin[1, i] + qin[2, i] + qin[3, i] + qin[4, i] + qin[5, i] + qin[6, i] + qin[7, i] + qin[8, i] + qin[9, i] + qin[10, i] + qin[11, i]
  # SAVE COMPUTE TIME
  if inpt.efinal <= ein[11]: nin = 10
  if inpt.efinal <= ein[10]: nin = 9
  if inpt.efinal <= ein[9]: nin = 8
  if inpt.efinal <= ein[8]: nin = 7
  if inpt.efinal <= ein[7]: nin = 6
  if inpt.efinal <= ein[6]: nin = 5
  if inpt.efinal <= ein[5]: nin = 4
  if inpt.efinal <= ein[4]: nin = 3
  if inpt.efinal <= ein[3]: nin = 2
  if inpt.efinal <= ein[2]: nin = 1
  if inpt.efinal <= ein[1]: nin = 0
  return
